// Generated by OpenAI Codex on 2026-11-01. Tokens remain in server-side sessions.
import { type ReactNode, useEffect, useState } from 'react';

const api = process.env.EXPO_PUBLIC_API_URL || 'http://localhost:8000/api';
type Session = { enabled: boolean; authenticated: boolean; email?: string };

export default function AuthGate({ children }: { children: ReactNode }) {
  const [session, setSession] = useState<Session | null>(null);
  const [error, setError] = useState(false);
  useEffect(() => {
    let active = true;
    let initialized = false;
    let checking = false;
    async function check() {
      if (checking) return;
      checking = true;
      try {
        const response = await fetch(`${api}/auth/session`, { credentials: 'include' });
        if (!response.ok) throw new Error('Session check failed');
        const data: Session = await response.json();

        if (!data.authenticated) initialized = false;
        if (data.authenticated && !initialized) {
          const userResponse = await fetch(`${api}/user/store-user`, {
            method: 'POST',
            credentials: 'include',
          });

          if (!userResponse.ok) {
            throw new Error('Could not initialize your account');
          }

          initialized = true;
        }

        if (active) {
          setSession(data);
          setError(false);
        }
      } catch {
        if (active) {
          setSession(null);
          setError(true);
        }
      } finally {
        checking = false;
      }
    }
    void check();
    const timer = setInterval(() => void check(), 60_000);
    return () => {
      active = false;
      clearInterval(timer);
    };
  }, []);
  if (!session || !session.authenticated) {
    return (
      <main style={{ padding: 48, fontFamily: 'system-ui', maxWidth: 560, margin: 'auto' }}>
        <h1>CATS</h1>
        <p>
          {error
            ? 'Unable to initialize your account or check your session. Please try again.'
            : session
              ? 'Sign in or create an account with your verified cmich.edu email.'
              : 'Checking your session…'}
        </p>
        {error && <button onClick={() => window.location.reload()}>Try again</button>}
        {session && (
          <button onClick={() => window.location.assign(`${api}/auth/login`)}>
            Sign in with Cognito
          </button>
        )}
      </main>
    );
  }
  async function logout() {
    const response = await fetch(`${api}/auth/logout`, { method: 'POST', credentials: 'include' });
    if (!response.ok) {
      setError(true);
      return;
    }
    const data = await response.json();
    window.location.assign(data.logout_url);
  }
  return (
    <>
      {children}
      {session.enabled && (
        <button
          onClick={() => void logout()}
          style={{ position: 'fixed', right: 16, bottom: 16, zIndex: 10000 }}
        >
          Sign out
        </button>
      )}
    </>
  );
}
